type void = |

let absurd : void -> 'a = fun v -> match v with _ -> .
let compose (f : 'a -> 'b) (g : 'b -> 'c) : 'a -> 'c = fun x -> g (f x)
let and_comm ((a, b) : 'a * 'b) : 'b * 'a = (b, a)

let or_comm : ('a, 'b) Either.t -> ('b, 'a) Either.t = function
  | Either.Left a -> Either.Right a
  | Either.Right b -> Either.Left b

let curry (f : 'a * 'b -> 'c) : 'a -> 'b -> 'c = fun a b -> f (a, b)
let uncurry (f : 'a -> 'b -> 'c) : 'a * 'b -> 'c = fun (a, b) -> f a b
let not_not_intro (a : 'a) : ('a -> void) -> void = fun k -> k a
let contrapositive (f : 'a -> 'b) : ('b -> void) -> 'a -> void = fun nb a -> nb (f a)

let distribute : 'a * ('b, 'c) Either.t -> ('a * 'b, 'a * 'c) Either.t = function
  | a, Either.Left b -> Either.Left (a, b)
  | a, Either.Right c -> Either.Right (a, c)

