let linear_search count x l = List.exists (fun y -> incr count; y = x) l

let binary_search count x a =
  let lo = ref 0 and hi = ref (Array.length a - 1) and found = ref false in
  while (not !found) && !lo <= !hi do
    incr count;
    let mid = (!lo + !hi) / 2 in
    if a.(mid) = x then found := true else if a.(mid) < x then lo := mid + 1 else hi := mid - 1
  done;
  !found

let insertion_sort count l =
  let rec insert x = function
    | [] -> [ x ]
    | y :: ys as l -> incr count; if x <= y then x :: l else y :: insert x ys
  in
  List.fold_left (fun acc x -> insert x acc) [] l

let merge_sort count l =
  let rec merge a b =
    match (a, b) with
    | [], l | l, [] -> l
    | x :: xs, y :: ys -> incr count; if x <= y then x :: merge xs b else y :: merge a ys
  in
  let rec sort l =
    match l with
    | [] | [ _ ] -> l
    | _ ->
        let half = List.length l / 2 in
        merge (sort (List.filteri (fun i _ -> i < half) l)) (sort (List.filteri (fun i _ -> i >= half) l))
  in
  sort l

